using System.ComponentModel.DataAnnotations;

namespace sv_7c6f0b5cd301466ca8a36f877f04b914.Components.Pages.Apply;

public class PersonalInfoModel
{
    [Required(ErrorMessage = "Full name is required.")]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Invalid phone number.")]
    public string Phone { get; set; } = "";

    [Required(ErrorMessage = "Address is required.")]
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    [Required(ErrorMessage = "Company name is required.")]
    public string Company { get; set; } = "";

    [Required(ErrorMessage = "Job title is required.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Start date is required.")]
    public DateTime? StartDate { get; set; }

    public DateTime? EndDate { get; set; }

    public bool IsCurrent { get; set; }

    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    [Required(ErrorMessage = "Name is required.")]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Relationship is required.")]
    public string Relationship { get; set; } = "";

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone is required.")]
    [Phone(ErrorMessage = "Invalid phone number.")]
    public string Phone { get; set; } = "";
}

@namespace sv_7c6f0b5cd301466ca8a36f877f04b914.Components.Pages.Apply

<nav class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var status = step < CurrentStep ? "completed"
                       : step == CurrentStep ? "active"
                       : "pending";

            <li class="step-item @status" @onclick="() => OnStepClick(step)">
                <div class="step-circle">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[step]</div>
            </li>

            @if (step < StepNames.Length - 1)
            {
                <li class="step-connector @(step < CurrentStep ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnNavigateToStep { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@namespace sv_7c6f0b5cd301466ca8a36f877f04b914.Components.Pages.Apply

.step-indicator ol {
    gap: 0;
    align-items: flex-start;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 0 0 auto;
    min-width: 90px;
    text-align: center;
}

.step-connector {
    flex: 1 1 auto;
    height: 2px;
    background-color: #dee2e6;
    margin-top: 18px;
    min-width: 20px;
}

.step-connector.completed {
    background-color: #198754;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.85rem;
    border: 2px solid #dee2e6;
    background-color: #fff;
    color: #adb5bd;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #0d6efd;
    background-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background-color: #198754;
    color: #fff;
    cursor: pointer;
}

.step-item.completed:hover .step-circle {
    background-color: #157347;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.78rem;
    color: #adb5bd;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
    cursor: pointer;
}

