@namespace sv_7c6f0b5cd301466ca8a36f877f04b914.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <InputText class="form-control" @bind-Value="Entry.Company" />
                <ValidationMessage For="() => Entry.Company" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <InputText class="form-control" @bind-Value="Entry.Title" />
                <ValidationMessage For="() => Entry.Title" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <InputDate class="form-control" @bind-Value="Entry.StartDate" />
                <ValidationMessage For="() => Entry.StartDate" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <InputDate class="form-control" @bind-Value="Entry.EndDate" disabled="@Entry.IsCurrent" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <InputCheckbox class="form-check-input" @bind-Value="Entry.IsCurrent"
                        @bind-Value:after="OnCurrentChanged" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <InputTextArea class="form-control" rows="3" @bind-Value="Entry.Description" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public WorkEntryModel Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool ShowRemove { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private void OnCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

